// Google Drive Operations Handler - Supports 17 operations
const op = $input.item.json.body.data.operation;
const data = $input.item.json.body.data;
let url, method, body, headers = {}, bodyRaw, rawContentType;

switch(op) {
  // FILE OPERATIONS
  case 'file.upload':
    url = 'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart';
    method = 'POST';
    body = {
      name: data.name,
      parents: data.parents || [],
      mimeType: data.mimeType
    };
    break;
  case 'file.createFromText':
    const boundaryTxt = 'n8nBoundary' + Date.now();
    const metadataTxt = {
      name: data.name,
      mimeType: data.mimeType || 'text/plain',
      parents: data.parents || []
    };
    const mediaTxt = data.content || '';
    bodyRaw = [
      `--${boundaryTxt}`,
      'Content-Type: application/json; charset=UTF-8',
      '',
      JSON.stringify(metadataTxt),
      `--${boundaryTxt}`,
      `Content-Type: ${data.mimeType || 'text/plain'}`,
      '',
      mediaTxt,
      `--${boundaryTxt}--`
    ].join('
');
    rawContentType = `multipart/related; boundary=${boundaryTxt}`;
    url = 'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart';
    method = 'POST';
    break;
  case 'file.createDocFromText':
    const boundaryDoc = 'n8nDocBoundary' + Date.now();
    const metadataDoc = {
      name: data.name,
      mimeType: 'application/vnd.google-apps.document'
    };
    if (data.folderId) {
      metadataDoc.parents = [data.folderId];
    }
    const docBody = data.documentContent || '';
    bodyRaw = [
      `--${boundaryDoc}`,
      'Content-Type: application/json; charset=UTF-8',
      '',
      JSON.stringify(metadataDoc),
      `--${boundaryDoc}`,
      'Content-Type: text/plain; charset=UTF-8',
      '',
      docBody,
      `--${boundaryDoc}--`
    ].join('
');
    rawContentType = `multipart/related; boundary=${boundaryDoc}`;
    url = 'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart';
    method = 'POST';
    break;
  case 'file.download':
    url = `https://www.googleapis.com/drive/v3/files/${data.fileId}?alt=media`;
    method = 'GET';
    break;
  case 'file.copy':
    url = `https://www.googleapis.com/drive/v3/files/${data.fileId}/copy`;
    method = 'POST';
    body = { name: data.newName, parents: data.parents };
    break;
  case 'file.move':
    url = `https://www.googleapis.com/drive/v3/files/${data.fileId}?addParents=${data.newParentId}&removeParents=${data.oldParentId}`;
    method = 'PATCH';
    break;
  case 'file.delete':
    url = `https://www.googleapis.com/drive/v3/files/${data.fileId}`;
    method = 'DELETE';
    break;
  case 'file.share':
    url = `https://www.googleapis.com/drive/v3/files/${data.fileId}/permissions`;
    method = 'POST';
    body = {
      role: data.role || 'reader',
      type: data.type || 'user',
      emailAddress: data.emailAddress
    };
    break;
  case 'file.update':
    url = `https://www.googleapis.com/drive/v3/files/${data.fileId}`;
    method = 'PATCH';
    body = {
      name: data.name,
      description: data.description
    };
    break;

  // FOLDER OPERATIONS
  case 'folder.create':
    url = 'https://www.googleapis.com/drive/v3/files';
    method = 'POST';
    body = {
      name: data.name,
      mimeType: 'application/vnd.google-apps.folder',
      parents: data.parents || []
    };
    break;
  case 'folder.delete':
    url = `https://www.googleapis.com/drive/v3/files/${data.folderId}`;
    method = 'DELETE';
    break;
  case 'folder.share':
    url = `https://www.googleapis.com/drive/v3/files/${data.folderId}/permissions`;
    method = 'POST';
    body = {
      role: data.role || 'reader',
      type: data.type || 'user',
      emailAddress: data.emailAddress
    };
    break;

  // SEARCH OPERATIONS
  case 'search':
    const query = data.query || `name contains '${data.name}'`;
    url = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(query)}&pageSize=${data.pageSize || 100}`;
    method = 'GET';
    break;

  // SHARED DRIVE OPERATIONS
  case 'sharedDrive.create':
    url = 'https://www.googleapis.com/drive/v3/drives?requestId=' + Date.now();
    method = 'POST';
    body = { name: data.name };
    break;
  case 'sharedDrive.delete':
    url = `https://www.googleapis.com/drive/v3/drives/${data.driveId}`;
    method = 'DELETE';
    break;
  case 'sharedDrive.get':
    url = `https://www.googleapis.com/drive/v3/drives/${data.driveId}`;
    method = 'GET';
    break;
  case 'sharedDrive.list':
    url = `https://www.googleapis.com/drive/v3/drives?pageSize=${data.pageSize || 100}`;
    method = 'GET';
    break;
  case 'sharedDrive.update':
    url = `https://www.googleapis.com/drive/v3/drives/${data.driveId}`;
    method = 'PATCH';
    body = { name: data.name };
    break;

  default:
    throw new Error(`Unsupported Drive operation: ${op}`);
}

return { json: { url, method, body, headers, operation: op, bodyRaw, rawContentType } };
